// CV filter: An LFO controls cutoff through a typed CV cable; base cutoff, resonance and depth stay live.
// Audition composition of public Rust primitives; not an instrument parity claim.
// Examples name imports so you can trace each tool to its module.
// Alternative: import * as manifold from '@manifold/author';
// Then use manifold.createGraphWorkspace(), manifold.gain, etc.
// Imports — each definition can be inspected in Manifold's primitive catalog.
import { createGraphWorkspace } from '@manifold/author';
import {
  lfo as lfoDefinition,
  modulatedSvf as modulatedSvfDefinition,
} from '@manifold/author/primitives';

export default function createProject() {
  // Interface — public paths and stable IDs preserve saved controls.
  const controls = {
    lfo_waveform: {
      "path": "/primitives/cv-filter/lfo/0",
      "label": "Waveform",
      "group": "LFO",
      "min": 0,
      "max": 2,
      "default": 0,
      "choices": [
        "Sine",
        "Triangle",
        "Square"
      ]
    },
    lfo_rate: {
      "path": "/primitives/cv-filter/lfo/1",
      "label": "Rate",
      "group": "LFO",
      "min": 0.05,
      "max": 20,
      "default": 1
    },
    filter_mode: {
      "path": "/primitives/cv-filter/filter/0",
      "label": "Mode",
      "group": "CV filter",
      "min": 0,
      "max": 3,
      "default": 0,
      "choices": [
        "Low pass",
        "Band pass",
        "High pass",
        "Notch"
      ]
    },
    filter_cutoff: {
      "path": "/primitives/cv-filter/filter/1",
      "label": "Cutoff",
      "group": "CV filter",
      "min": 20,
      "max": 20000,
      "default": 2000
    },
    filter_resonance: {
      "path": "/primitives/cv-filter/filter/2",
      "label": "Resonance",
      "group": "CV filter",
      "min": 0.1,
      "max": 1,
      "default": 0.75
    },
    filter_cvDepthHz: {
      "path": "/primitives/cv-filter/filter/3",
      "label": "CV depth Hz",
      "group": "CV filter",
      "min": 0,
      "max": 20000,
      "default": 5000
    },
  };

  // Audio inputs and outputs — the host supplies the external audio input.
  const graph = createGraphWorkspace().setInputSource('external');
  const input = graph.input.output('out');
  const output = graph.output.input('in');

  // DSP instances — parameters belong to these named instances.
  const lfo = graph.add(lfoDefinition.type, {"id":4});
  graph.registerInstance('/primitives/cv-filter/lfo', lfo);
  lfo.parameter('waveform').expose(controls.lfo_waveform);
  lfo.parameter('rate').expose(controls.lfo_rate);

  const filter = graph.add(modulatedSvfDefinition.type, {"id":5});
  graph.registerInstance('/primitives/cv-filter/filter', filter);
  filter.parameter('mode').expose(controls.filter_mode);
  filter.parameter('cutoff').expose(controls.filter_cutoff);
  filter.parameter('resonance').expose(controls.filter_resonance);
  filter.parameter('cvDepthHz').expose(controls.filter_cvDepthHz);

  // Composition — named ports make the audio and control paths visible.
  graph.connect(input, filter.input('audio'));
  graph.connect(lfo.output('uni'), filter.input('cv'));
  graph.connect(filter.output('out'), output);

  // Presentation — both renderers bind to the controls declared above.
  const view = [
    controls.lfo_waveform,
    controls.lfo_rate,
    controls.filter_mode,
    controls.filter_cutoff,
    controls.filter_resonance,
    controls.filter_cvDepthHz
  ].map(control => ({
    id: control.path, type: 'parameter', path: control.path,
    label: control.label, group: control.group,
    ...(control.choices ? { choices: control.choices } : {}),
  }));
  function paint(ui) {
    for (const component of view) {
      if (component.type === 'label') ui.label(component.label, component.id);
      else ui.parameter(component.path, component);
    }
  }

  // The host uses this project declaration for audio, UI, save and live edits.
  return { graph, view, paint };
}
